const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'attachment_0');

  const mimeType =
    items[i].binary?.attachment_0?.mimeType || 'image/jpeg';

  items[i].json.image_base64 = buffer.toString('base64');
  items[i].json.image_mime_type = mimeType;
}

return items;

